// Check for any element that looks like a panel title in Grafana
let panelTitles = [];
// Grafana v10+ uses data-panelid on panel wrapper divs
document.querySelectorAll('[class*="panel"], section').forEach(el => {
  const h = el.querySelector('h1, h2, h3, h4, h5, h6, span[class*="title"], div[class*="title"]');
  if (h && !panelTitles.includes(h.textContent.trim())) panelTitles.push(h.textContent.trim());
});
panelTitles
